import { describe, expect, it } from "bun:test"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { type EffortLevel, resolveEffort } from "./effort"

function catalog(
  modelId: string,
  efforts?: Array<EffortLevel>,
): ModelsResponse {
  return {
    object: "list",
    data: [
      {
        id: modelId,
        name: modelId,
        object: "model",
        vendor: "test",
        version: "1",
        preview: false,
        model_picker_enabled: true,
        capabilities: {
          family: modelId,
          limits: {},
          object: "model_capabilities",
          supports: { reasoning_effort: efforts },
          tokenizer: "test",
          type: "chat",
        },
      },
    ],
  }
}

describe("resolveEffort", () => {
  it("preserves exact supported values", () => {
    expect(
      resolveEffort({
        modelId: "gpt-5.6-sol",
        requested: "max",
        cachedModels: catalog("gpt-5.6-sol", [
          "none",
          "low",
          "medium",
          "high",
          "xhigh",
          "max",
        ]),
      }),
    ).toBe("max")
  })

  it("falls back to the strongest supported effort below the request", () => {
    expect(
      resolveEffort({
        modelId: "gpt-5.5",
        requested: "max",
        cachedModels: catalog("gpt-5.5", [
          "none",
          "low",
          "medium",
          "high",
          "xhigh",
        ]),
      }),
    ).toBe("xhigh")
    expect(
      resolveEffort({
        modelId: "claude-opus-4.6",
        requested: "xhigh",
        cachedModels: catalog("claude-opus-4.6", [
          "low",
          "medium",
          "high",
          "max",
        ]),
      }),
    ).toBe("high")
  })

  it("uses the model floor when the request is weaker than every supported value", () => {
    expect(
      resolveEffort({
        modelId: "gemini-3.5-flash",
        requested: "none",
        cachedModels: catalog("gemini-3.5-flash", [
          "minimal",
          "low",
          "medium",
          "high",
        ]),
      }),
    ).toBe("minimal")
  })

  it("treats auto and omission as the supplied route default", () => {
    const models = catalog("gpt-5.5", [
      "none",
      "low",
      "medium",
      "high",
      "xhigh",
    ])
    expect(
      resolveEffort({
        modelId: "gpt-5.5",
        requested: "auto",
        cachedModels: models,
        defaultEffort: "medium",
      }),
    ).toBe("medium")
    expect(
      resolveEffort({
        modelId: "gpt-5.5",
        cachedModels: models,
        defaultEffort: "medium",
      }),
    ).toBe("medium")
    expect(
      resolveEffort({
        modelId: "gpt-5.5",
        requested: "auto",
        cachedModels: models,
      }),
    ).toBeUndefined()
  })

  it("omits effort for a known model without the capability", () => {
    expect(
      resolveEffort({
        modelId: "legacy",
        requested: "high",
        cachedModels: catalog("legacy"),
      }),
    ).toBeUndefined()
  })

  it("preserves a recognized effort when catalog data is unavailable", () => {
    expect(resolveEffort({ modelId: "unknown", requested: "high" })).toBe(
      "high",
    )
    expect(
      resolveEffort({
        modelId: "unknown",
        requested: "max",
        cachedModels: { data: [] },
      }),
    ).toBe("max")
  })

  it("rejects unknown effort strings", () => {
    expect(
      resolveEffort({ modelId: "gpt-5.6-sol", requested: "extreme" }),
    ).toBeUndefined()
  })

  it("omits effort when the catalog advertises only unknown values", () => {
    const models = catalog("future", ["high"])
    models.data[0].capabilities.supports.reasoning_effort = [
      "extreme" as EffortLevel,
    ]

    expect(
      resolveEffort({
        modelId: "future",
        requested: "high",
        cachedModels: models,
      }),
    ).toBeUndefined()
  })
})

import consola from "consola"

export type EffortLevel =
  | "none"
  | "minimal"
  | "low"
  | "medium"
  | "high"
  | "xhigh"
  | "max"

export type RequestedEffort = EffortLevel | "auto"

interface EffortCatalog {
  data: Array<{
    id: string
    capabilities: {
      supports: {
        reasoning_effort?: Array<EffortLevel>
      }
    }
  }>
}

const EFFORT_ORDER: Array<EffortLevel> = [
  "none",
  "minimal",
  "low",
  "medium",
  "high",
  "xhigh",
  "max",
]

const EFFORT_RANK = new Map(
  EFFORT_ORDER.map((effort, index) => [effort, index]),
)

interface ResolveEffortOptions {
  modelId: string
  requested?: string
  cachedModels?: EffortCatalog
  defaultEffort?: EffortLevel
}

export function resolveEffort({
  modelId,
  requested,
  cachedModels,
  defaultEffort,
}: ResolveEffortOptions): EffortLevel | undefined {
  const candidate =
    requested === "auto" || !requested ? defaultEffort : requested
  if (!candidate) return undefined

  const candidateRank = EFFORT_RANK.get(candidate as EffortLevel)
  if (candidateRank === undefined) {
    consola.warn(`Ignoring unknown reasoning effort "${candidate}"`)
    return undefined
  }

  const model = cachedModels?.data.find((item) => item.id === modelId)
  if (!model) return candidate as EffortLevel

  const supported = model.capabilities.supports.reasoning_effort
  if (!supported?.length) return undefined
  if (supported.includes(candidate as EffortLevel)) {
    return candidate as EffortLevel
  }

  const rankedSupported = supported.flatMap((effort) => {
    const rank = EFFORT_RANK.get(effort)
    return rank === undefined ? [] : [{ effort, rank }]
  })
  if (rankedSupported.length === 0) {
    consola.warn(`Model ${modelId} advertises no recognized reasoning efforts`)
    return undefined
  }
  rankedSupported.sort((a, b) => a.rank - b.rank)

  const fallback =
    rankedSupported.findLast((item) => item.rank <= candidateRank)
    ?? rankedSupported[0]

  consola.warn(
    `Model ${modelId} does not support reasoning effort ${candidate}; using ${fallback.effort}`,
  )
  return fallback.effort
}

import type { EffortLevel } from "./effort"

import { state } from "./state"

// Forward map: Anthropic dash format → Copilot dot format
const MODEL_ID_MAP: Record<string, string> = {
  "claude-opus-4-7": "claude-opus-4.7",
  "claude-opus-4-6": "claude-opus-4.6",
  "claude-opus-4-5": "claude-opus-4.5",
  "claude-sonnet-4-6": "claude-sonnet-4.6",
  "claude-sonnet-4-5": "claude-sonnet-4.5",
  "claude-sonnet-4": "claude-sonnet-4",
  "claude-opus-4": "claude-opus-4",
  "claude-haiku-4-5": "claude-haiku-4.5",
}

/** Legacy effort suffixes that may appear in model names from old configs */
const EFFORT_SUFFIXES: ReadonlyArray<`-${EffortLevel}`> = [
  "-xhigh",
  "-high",
  "-max",
  "-medium",
  "-low",
]

// Reverse map: Copilot dot format → Anthropic dash format
const REVERSE_MODEL_ID_MAP: Record<string, string> = Object.fromEntries(
  Object.entries(MODEL_ID_MAP).map(([k, v]) => [v, k]),
)

/**
 * Strip a legacy effort suffix from a model name.
 * Returns the base name and the effort value (without the dash prefix).
 */
export function extractEffortFromModelName(model: string): {
  base: string
  effort: EffortLevel | undefined
} {
  for (const suffix of EFFORT_SUFFIXES) {
    if (model.endsWith(suffix)) {
      return {
        base: model.slice(0, -suffix.length),
        effort: suffix.slice(1) as EffortLevel, // strip leading dash
      }
    }
  }
  return { base: model, effort: undefined }
}

/**
 * Convert an Anthropic-style model ID to a Copilot-style model ID.
 * Strips date suffixes, effort suffixes, converts dashes to dots,
 * and appends -1m if needed.
 */
export function anthropicToCopilotModelId(
  model: string,
  is1M: boolean,
): string {
  let base = model

  // Strip [1m] suffix if present (Claude Code sends this)
  const has1MBracket = base.endsWith("[1m]")
  if (has1MBracket) {
    base = base.slice(0, -4)
  }

  // Strip -1m suffix if present (legacy config format)
  const has1MDash = !has1MBracket && base.endsWith("-1m")
  if (has1MDash) {
    base = base.slice(0, -3)
  }

  // Strip legacy effort suffixes (e.g. claude-opus-4-7-xhigh → claude-opus-4-7)
  const { base: withoutEffort } = extractEffortFromModelName(base)
  base = withoutEffort

  // Strip date suffixes (e.g. claude-sonnet-4-20250514 → claude-sonnet-4)
  if (/^claude-sonnet-4-\d{8}/.test(base)) {
    base = "claude-sonnet-4"
  } else if (/^claude-opus-4-\d{8}/.test(base)) {
    base = "claude-opus-4"
  }

  const mapped = MODEL_ID_MAP[base] ?? base

  const use1M = is1M || has1MBracket || has1MDash

  // Only append -1m if the 1M variant actually exists in the model catalog
  if (use1M) {
    const candidate = `${mapped}-1m`
    const exists = state.models?.data.some((m) => m.id === candidate)
    if (exists) return candidate
  }

  return mapped
}

/**
 * Convert a Copilot-style model ID back to Anthropic-style.
 * Converts dots to dashes and maps -1m back to [1m].
 * Strips -internal suffix (transient preview artifact).
 * Effort is handled via output_config in the request body, not in the model ID.
 */
export function copilotToAnthropicModelId(copilotModel: string): string {
  let base = copilotModel

  // Strip -internal (transient preview suffix)
  if (base.endsWith("-internal")) base = base.slice(0, -9)

  // Strip -1m
  const is1M = base.endsWith("-1m")
  if (is1M) base = base.slice(0, -3)

  const mapped = REVERSE_MODEL_ID_MAP[base] ?? base
  return is1M ? `${mapped}[1m]` : mapped
}

import type { Context } from "hono"

import consola from "consola"
import { streamSSE, type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import { openaiToAnthropicPayload } from "~/routes/messages/non-stream-translation"
import {
  createChatCompletions,
  type ChatCompletionResponse,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"
import {
  forwardNativeMessagesNonStreaming,
  forwardNativeMessagesStreaming,
} from "~/services/copilot/forward-native-messages"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  if (isNullish(payload.max_tokens)) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Reroute Claude models to native /v1/messages passthrough
  // Claude on /chat/completions loses tool calling and other native features
  if (endpoint === "/v1/messages") {
    consola.debug(
      `Rerouting Claude model ${payload.model} to native /v1/messages`,
    )
    payload.reasoning_effort = resolveEffort({
      modelId: payload.model,
      requested: payload.reasoning_effort,
      cachedModels: state.models,
    })
    return handleNativeReroute(c, payload)
  }

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const response = await createChatCompletions(payload, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming response:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming response")
  return streamSSE(c, async (stream) => {
    try {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        await stream.writeSSE(chunk as SSEMessage)
      }
    } catch (err) {
      if (
        signal.aborted
        || (err instanceof Error && err.name === "AbortError")
      ) {
        consola.debug("chat-completions stream aborted by client")
        return
      }
      throw err
    }
  })
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const response = await createResponses(payload, effort, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming /responses result:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming /responses response")
  return streamSSE(c, async (stream) => {
    const streamState = createResponsesStreamState()

    try {
      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    } catch (err) {
      if (
        signal?.aborted
        || (err instanceof Error && err.name === "AbortError")
      ) {
        consola.debug("/responses stream aborted by client")
        return
      }
      throw err
    }
  })
}

const isNonStreaming = (
  response: Awaited<ReturnType<typeof createChatCompletions>>,
): response is ChatCompletionResponse => Object.hasOwn(response, "choices")

/**
 * Reroute a /chat/completions request for a Claude model through
 * native /v1/messages passthrough. Translates OpenAI→Anthropic,
 * forwards natively, translates Anthropic→OpenAI back.
 */
async function handleNativeReroute(
  c: Context,
  payload: ChatCompletionsPayload,
) {
  const anthropicPayload = openaiToAnthropicPayload(payload)

  if (!payload.stream) {
    const response = await forwardNativeMessagesNonStreaming(anthropicPayload)
    return c.json(
      anthropicResponseToOpenAI(response as Record<string, unknown>),
    )
  }

  return streamSSE(c, async (stream) => {
    for await (const event of forwardNativeMessagesStreaming(
      anthropicPayload,
    )) {
      // Translate Anthropic SSE events to OpenAI chunks
      const chunk = anthropicEventToOpenAIChunk(event)
      if (chunk) {
        await stream.writeSSE({
          data: JSON.stringify(chunk),
        })
      }
    }
  })
}

/**
 * Convert Anthropic stop_reason to OpenAI finish_reason.
 */
function mapAnthropicFinishReason(
  stopReason: string | null | undefined,
): "stop" | "length" | "tool_calls" | "content_filter" {
  if (stopReason === "tool_use") return "tool_calls"
  if (stopReason === "max_tokens") return "length"
  return "stop"
}

/**
 * Extract text and tool calls from Anthropic content blocks.
 */
function extractAnthropicContent(
  content: Array<{
    type: string
    text?: string
    id?: string
    name?: string
    input?: unknown
  }>,
): {
  text: string
  toolCalls: Array<{
    id: string
    type: "function"
    function: { name: string; arguments: string }
  }>
} {
  let text = ""
  const toolCalls: Array<{
    id: string
    type: "function"
    function: { name: string; arguments: string }
  }> = []

  for (const block of content) {
    if (block.type === "text" && block.text) {
      text += block.text
    } else if (block.type === "tool_use" && block.name && block.id) {
      toolCalls.push({
        id: block.id,
        type: "function",
        function: {
          name: block.name,
          arguments: JSON.stringify(block.input ?? {}),
        },
      })
    }
  }

  return { text, toolCalls }
}

/**
 * Convert a raw Anthropic Messages response to OpenAI Chat Completion format.
 */
function anthropicResponseToOpenAI(
  resp: Record<string, unknown>,
): ChatCompletionResponse {
  const rawContent = resp.content as
    | Array<{
        type: string
        text?: string
        id?: string
        name?: string
        input?: unknown
      }>
    | undefined
  const content = rawContent ?? []
  const { text, toolCalls } = extractAnthropicContent(content)
  const finishReason = mapAnthropicFinishReason(
    resp.stop_reason as string | null,
  )
  const rawUsage = resp.usage as
    | { input_tokens: number; output_tokens: number }
    | undefined
  const usage =
    rawUsage ?
      {
        prompt_tokens: rawUsage.input_tokens,
        completion_tokens: rawUsage.output_tokens,
        total_tokens: rawUsage.input_tokens + rawUsage.output_tokens,
      }
    : undefined

  return {
    id: typeof resp.id === "string" ? resp.id : "",
    object: "chat.completion",
    created: Math.floor(Date.now() / 1000),
    model: typeof resp.model === "string" ? resp.model : "",
    choices: [
      {
        index: 0,
        message: {
          role: "assistant",
          content: text || null,
          ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
        },
        logprobs: null,
        finish_reason: finishReason,
      },
    ],
    usage,
  }
}

/**
 * Convert an Anthropic SSE event to an OpenAI streaming chunk.
 */
function anthropicEventToOpenAIChunk(event: {
  type: string
  data: Record<string, unknown>
}): Record<string, unknown> | null {
  const { type, data } = event

  if (type === "content_block_delta") {
    const delta = data.delta as { type: string; text?: string } | undefined
    if (delta?.type === "text_delta" && delta.text) {
      return {
        object: "chat.completion.chunk",
        choices: [
          { index: 0, delta: { content: delta.text }, finish_reason: null },
        ],
      }
    }
  }

  if (type === "message_delta") {
    const delta = data.delta as Record<string, unknown> | undefined
    const stopReason = delta?.stop_reason as string | undefined
    if (stopReason) {
      return {
        object: "chat.completion.chunk",
        choices: [
          {
            index: 0,
            delta: {},
            finish_reason: mapAnthropicFinishReason(stopReason),
          },
        ],
      }
    }
  }

  return null
}

import type { RequestedEffort } from "~/lib/effort"

// Anthropic API Types

export interface AnthropicMessagesPayload {
  model: string
  messages: Array<AnthropicMessage>
  max_tokens: number
  system?: string | Array<AnthropicTextBlock>
  metadata?: {
    user_id?: string
  }
  stop_sequences?: Array<string>
  stream?: boolean
  temperature?: number
  top_p?: number
  top_k?: number
  tools?: Array<AnthropicTool>
  tool_choice?: {
    type: "auto" | "any" | "tool" | "none"
    name?: string
  }
  thinking?: {
    type: "enabled" | "disabled" | "adaptive"
    budget_tokens?: number
  }
  service_tier?: "auto" | "standard_only"
  output_config?: {
    effort?: RequestedEffort
    [key: string]: unknown
  }
}

export interface AnthropicTextBlock {
  type: "text"
  text: string
}

export interface AnthropicImageBlock {
  type: "image"
  source: {
    type: "base64"
    media_type: "image/jpeg" | "image/png" | "image/gif" | "image/webp"
    data: string
  }
}

export interface AnthropicToolResultBlock {
  type: "tool_result"
  tool_use_id: string
  content: string
  is_error?: boolean
}

export interface AnthropicToolUseBlock {
  type: "tool_use"
  id: string
  name: string
  input: Record<string, unknown>
}

export interface AnthropicThinkingBlock {
  type: "thinking"
  thinking: string
}

export type AnthropicUserContentBlock =
  | AnthropicTextBlock
  | AnthropicImageBlock
  | AnthropicToolResultBlock

export type AnthropicAssistantContentBlock =
  | AnthropicTextBlock
  | AnthropicToolUseBlock
  | AnthropicThinkingBlock

export interface AnthropicUserMessage {
  role: "user"
  content: string | Array<AnthropicUserContentBlock>
}

export interface AnthropicAssistantMessage {
  role: "assistant"
  content: string | Array<AnthropicAssistantContentBlock>
}

export type AnthropicMessage = AnthropicUserMessage | AnthropicAssistantMessage

export interface AnthropicTool {
  name: string
  description?: string
  input_schema: Record<string, unknown>
}

export interface AnthropicResponse {
  id: string
  type: "message"
  role: "assistant"
  content: Array<AnthropicAssistantContentBlock>
  model: string
  stop_reason:
    | "end_turn"
    | "max_tokens"
    | "stop_sequence"
    | "tool_use"
    | "pause_turn"
    | "refusal"
    | null
  stop_sequence: string | null
  usage: {
    input_tokens: number
    output_tokens: number
    cache_creation_input_tokens?: number
    cache_read_input_tokens?: number
    service_tier?: "standard" | "priority" | "batch"
  }
}

export type AnthropicResponseContentBlock = AnthropicAssistantContentBlock

// Anthropic Stream Event Types
export interface AnthropicMessageStartEvent {
  type: "message_start"
  message: Omit<
    AnthropicResponse,
    "content" | "stop_reason" | "stop_sequence"
  > & {
    content: []
    stop_reason: null
    stop_sequence: null
  }
}

export interface AnthropicContentBlockStartEvent {
  type: "content_block_start"
  index: number
  content_block:
    | { type: "text"; text: string }
    | (Omit<AnthropicToolUseBlock, "input"> & {
        input: Record<string, unknown>
      })
    | { type: "thinking"; thinking: string }
}

export interface AnthropicContentBlockDeltaEvent {
  type: "content_block_delta"
  index: number
  delta:
    | { type: "text_delta"; text: string }
    | { type: "input_json_delta"; partial_json: string }
    | { type: "thinking_delta"; thinking: string }
    | { type: "signature_delta"; signature: string }
}

export interface AnthropicContentBlockStopEvent {
  type: "content_block_stop"
  index: number
}

export interface AnthropicMessageDeltaEvent {
  type: "message_delta"
  delta: {
    stop_reason?: AnthropicResponse["stop_reason"]
    stop_sequence?: string | null
  }
  usage?: {
    input_tokens?: number
    output_tokens: number
    cache_creation_input_tokens?: number
    cache_read_input_tokens?: number
  }
}

export interface AnthropicMessageStopEvent {
  type: "message_stop"
}

export interface AnthropicPingEvent {
  type: "ping"
}

export interface AnthropicErrorEvent {
  type: "error"
  error: {
    type: string
    message: string
  }
}

export type AnthropicStreamEventData =
  | AnthropicMessageStartEvent
  | AnthropicContentBlockStartEvent
  | AnthropicContentBlockDeltaEvent
  | AnthropicContentBlockStopEvent
  | AnthropicMessageDeltaEvent
  | AnthropicMessageStopEvent
  | AnthropicPingEvent
  | AnthropicErrorEvent

// State for streaming translation
export interface AnthropicStreamState {
  messageStartSent: boolean
  contentBlockIndex: number
  contentBlockOpen: boolean
  toolCalls: {
    [openAIToolIndex: number]: {
